NAME = 'GerTafel: German Tafelbibel (1911)'
BOOK = 'Haggai'

CHAPTERS = {
    1: {
        1: 'Im zweiten Jahr des Königs Darius, im sechsten Monat, am ersten Tag des Monats geschah das Wort Jehovahs durch die Hand Chaggais, des Propheten, an Serubbabel, den Sohn Schealthiels, den Statthalter Jehudahs, und an Jehoschua, den Sohn Jehozadaks, den Hohenpriester, und sprach:',
        2: 'So spricht Jehovah der Heerscharen und sagt: Dies Volk spricht: Die Zeit ist nicht gekommen, die Zeit, Jehovahs Haus zu bauen.',
        3: 'Und es geschah Jehovahs Wort durch die Hand Chaggais, des Propheten, und sprach:',
        4: 'Ist die Zeit da für euch, daß ihr in euren getäfelten Häusern sitzet und dieses Haus ist verödet?',
        5: 'Nun aber spricht Jehovah der Heerscharen also: Richtet euer Herz auf eure Wege!',
        6: 'Ihr sät viel und bringt wenig herein. Ihr esset, und nicht zur Sättigung; ihr trinkt, und nicht zur Trunkenheit, ihr kleidet euch und werdet nicht warm; und was ihr verdient, verdient ihr in einen löchrigen Beutel.',
        7: 'So spricht Jehovah der Heerscharen: Richtet euer Herz auf eure Wege!',
        8: 'Steigt auf den Berg und bringt Holz herein und baut das Haus, daß Ich daran Wohlgefallen habe und verherrlicht werde! spricht Jehovah.',
        9: 'Ihr wandtet euch auf viel, und siehe, es ward zu wenig; und ihr brachtet es zum Haus herein, und Ich blies darein. Warum? spricht Jehovah der Heerscharen. Um Meines Hauses willen, das verödet ist, und ihr laufet, jeder Mann nach seinem Haus.',
        10: 'Darum verhalten die Himmel euch den Tau, und die Erde verhält ihr Gewächs.',
        11: 'Und Ich rief die Dürre über die Erde und über die Berge und über das Korn und über den Most und über das Öl und über das, was der Boden hervorbringt, und über Mensch, über Vieh, und über alle Arbeit der Hände.',
        12: 'Und Serubbabel, der Sohn Schealthiels, und Jehoschua, der Sohn Jehozadaks, der Hohepriester, und all der Überrest des Volkes hörten auf die Stimme Jehovahs, ihres Gottes, und auf die Worte Chaggais, des Propheten, wie ihn Jehovah, ihr Gott, hatte gesandt; und das Volk fürchtete sich vor dem Angesichte Jehovahs.',
        13: 'Und Chaggai, der Bote Jehovahs, sprach in der Botschaft Jehovahs zum Volk und sagte: Ich bin mit euch, spricht Jehovah.',
        14: 'Und Jehovah erregte den Geist Serubbabels, des Sohns Schealthiels, des Statthalters Jehudahs, und den Geist Jehoschuas, des Sohnes Jehozadaks, des Hohenpriesters, und den Geist all des Überrests vom Volk; und sie kamen und taten das Werk am Hause Jehovahs der Heerscharen, ihres Gottes,',
        15: 'Am vierundzwanzigsten Tag des Monats im sechsten im zweiten Jahr des Königs Darius.',
    },
    2: {
        1: 'Im siebenten, am einundzwanzigsten des Monats geschah das Wort Jehovahs durch die Hand Chaggais, des Propheten, und Er sprach:',
        2: 'Sprich doch zu Serubbabel, dem Sohn Schealthiels, dem Statthalter Jehudahs, und zu Jehoschua, dem Sohn Jehozadaks, dem Hohenpriester, und zu dem Überrest des Volkes und sprich:',
        3: 'Wer ist unter euch übriggeblieben, der dieses Haus in seiner ersten Herrlichkeit gesehen hat? Und wie seht ihr es jetzt? Ist es nicht im Vergleich wie nichts in euren Augen?',
        4: 'Und nun sei stark, Serubbabel, spricht Jehovah, und sei stark, Jehoschua, Sohn Jehozadaks, du Hoherpriester, und sei stark, alles Volk des Landes, spricht Jehovah, und macht es; denn Ich bin mit euch, spricht Jehovah der Heerscharen.',
        5: 'Mit dem Worte, mit dem Ich mit euch abgeschlossen, da ihr aus Ägypten auszogt, und mit Meinem Geiste, der in eurer Mitte steht, fürchtet euch nicht!',
        6: 'Denn so spricht Jehovah der Heerscharen: Noch ein Kleines ist es, so lasse Ich die Himmel und die Erde erbeben und das Meer und das Trockene.',
        7: 'Und Ich lasse alle Völkerschaften erbeben, daß komme die Begehr aller Völkerschaften, und Ich erfülle dieses Haus mit Herrlichkeit, spricht Jehovah der Heerscharen.',
        8: 'Mein ist das Silber und Mein das Gold, spricht Jehovah der Heerscharen.',
        9: 'Größer wird sein die Herrlichkeit dieses späteren Hauses als die des ersten, spricht Jehovah der Heerscharen, und an diesem Orte will Ich Frieden geben, spricht Jehovah der Heerscharen.',
        10: 'Am vierundzwanzigsten des neunten im zweiten Jahr des Darius geschah das Wort Jehovahs durch die Hand Chaggais, des Propheten, und sprach:',
        11: 'So spricht Jehovah der Heerscharen: Frage doch die Priester über das Gesetz und sprich:',
        12: 'Siehe, ein Mann trägt Fleisch der Heiligkeit im Zipfel seines Kleides und berührt mit seinem Zipfel Brot und Gekochtes, und Wein und Öl, und irgendwelche Speise, wird es geheiligt? Und die Priester antworteten und sprachen: Nein.',
        13: 'Und Chaggai sprach: Wo aber ein durch eine Seele Unreiner dieser irgendeines anrührt, wird es unrein? Und die Priester antworteten und sprachen: Es wird unrein.',
        14: 'Und Chaggai antwortete und sprach: So ist dies Volk und so ist diese Völkerschaft vor Meinem Angesicht, spricht Jehovah, und so alles Tun ihrer Hände, und was sie allda darbringen, ist unrein.',
        15: 'Und nun richtet doch euer Herz darauf von dem Tage an und weiter: Ehe man Stein legt auf Stein am Tempel Jehovahs;',
        16: 'Vor diesem, kam man zum Kornhaufen von zwanzigen, so waren es zehn; kam man zur Kufe, um fünfzig zu schöpfen aus der Kelter, so waren es zwanzig.',
        17: 'Ich schlug euch mit Kornbrand, und mit Vergilbung und mit Hagel in allem Tun eurer Hände; und doch wollt ihr nicht zu Mir, spricht Jehovah.',
        18: 'So richtet euer Herz darauf von diesem Tage an und weiter, vom vierundzwanzigsten des neunten, von dem Tage an, da der Tempel Jehovahs gegründet ward, darauf richtet euer Herz.',
        19: 'Ist nicht die Saat noch in dem Speicher? Und bis auf den Weinstock und den Feigenbaum und den Granatbaum und den Baum der Oliven, die nicht getragen, will Ich segnen von diesem Tage an.',
        20: 'Und es geschah das Wort Jehovahs zum zweitenmal an Chaggai am vierundzwanzigsten des Monats, und Er sprach:',
        21: 'Sprich zu Serubbabel, dem Statthalter Jehudahs, und sage: Ich lasse erbeben die Himmel und die Erde,',
        22: 'Und kehre um den Thron von Königreichen, und vernichte die Stärke der Königreiche der Völkerschaften, und kehre um die Streitwagen und die darin fahren; und das Roß und dessen Reiter sollen herabstürzen, der Mann durch das Schwert seines Bruders.',
        23: 'An diesem Tage, spricht Jehovah der Heerscharen, nehme Ich dich, Serubbabel, Sohn Schealthiels, meinen Knecht, spricht Jehovah, und setze dich, wie den Siegelring; denn dich habe Ich erwählt, spricht Jehovah der Heerscharen..',
    },
}
